actions.script:
def csv = ec.screen.makeRender()
    .rootScreen('component://zenith-erp-inventory/screen/zenith/inventory/Inventory/StockLevels.xml')
    .renderMode('csv').render()
def records = org.apache.commons.csv.CSVFormat.DEFAULT.parse(new java.io.StringReader(csv)).records
def escape = { value -> groovy.xml.XmlUtil.escapeXml(value ?: '') }
def sheet = new StringBuilder('<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>')
records.eachWithIndex { record, rowIndex ->
    sheet.append('<row r="').append(rowIndex + 1).append('">')
    // Nine data columns; the CSV's empty action column has no place in a workbook.
    for (int column = 0; column < Math.min(record.size(), 9); column++) {
        def value = record.get(column)
        def ref = ((char)(65 + column)).toString() + (rowIndex + 1)
        if (rowIndex > 0 && column in [4,5,6,7] && value) {
            sheet.append('<c r="').append(ref).append('" t="n"><v>')
                .append(new java.math.BigDecimal(value.replace(',', '')).toPlainString()).append('</v></c>')
        } else {
            sheet.append('<c r="').append(ref).append('" t="inlineStr"><is><t xml:space="preserve">')
                .append(escape(value)).append('</t></is></c>')
        }
    }
    sheet.append('</row>')
}
sheet.append('</sheetData></worksheet>')
def files = [
    '[Content_Types].xml':'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>',
    '_rels/.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
    'xl/workbook.xml':'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Stock Levels" sheetId="1" r:id="rId1"/></sheets></workbook>',
    'xl/_rels/workbook.xml.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>',
    'xl/worksheets/sheet1.xml':sheet.toString()
]
def bytes = new java.io.ByteArrayOutputStream()
def zip = new java.util.zip.ZipOutputStream(bytes)
files.each { path, content ->
    zip.putNextEntry(new java.util.zip.ZipEntry(path))
    zip.write(content.getBytes('UTF-8'))
    zip.closeEntry()
}
zip.close()
ec.web.response.setContentType('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
ec.web.response.setHeader('Content-Disposition', 'attachment; filename="StockLevelForm.xlsx"')
ec.web.response.outputStream.write(bytes.toByteArray())

// An explicitly empty facility means All Warehouses, even with an active shop.
_stockOrgId = ec.user.getPreference('ACTIVE_ORGANIZATION') ?: '__NO_ACTIVE_ORG__'
_stockExport = sri.renderMode in ['csv', 'xlsx']
stockSearchParams = ec.context + [:]
if (_stockExport) {
    stockSearchParams.putAll([pageNoLimit:'true', pageIndex:null, pageSize:null])
}
_stockFac = null
if (ec.web.requestParameters.containsKey('facilityId')) {
    _stockFac = ec.web.requestParameters.facilityId?.toString()?.trim() ?: null
} else {
    def scope = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call()
    _stockFac = scope?.activeShopId
}
if (_stockFac == '__ALL_WAREHOUSES__') _stockFac = null
// Keep All selected through native search/sort/page links, which drop empty parameters.
stockSearchParams.facilityId = _stockFac
context.facilityId = _stockFac ?: '__ALL_WAREHOUSES__'
stockPagePath = ec.web.request.requestURI.replaceFirst(/\.(qvt|vuet)$/, '')
stockFilterParams = [:]
for (name in ['pseudoId', 'productName', 'hsnCode', 'orderByField']) {
    for (key in [name, name + '_op', name + '_ic', name + '_not']) {
        def value = ec.web.requestParameters[key]
        if (value instanceof Collection) value = key == 'orderByField' ? value.join(',') : value[0]
        if (value != null) stockFilterParams[key] = value.toString()
    }
}
def exportParams = new LinkedHashMap(stockFilterParams)
exportParams.putAll([facilityId:(_stockFac ?: '__ALL_WAREHOUSES__'), renderMode:'csv',
    saveFilename:'StockLevelForm.csv', pageNoLimit:'true', lastStandalone:'true'])
stockExportUrl = stockPagePath + '?' + exportParams.collect { key, value ->
    java.net.URLEncoder.encode(key, 'UTF-8') + '=' + java.net.URLEncoder.encode(value, 'UTF-8')
}.join('&')
stockFilterFields = stockFilterParams.collect { key, value -> [paramName:key, paramValue:value] }
stockXlsxUrl = stockPagePath + '/exportXlsx?' +
    (stockFilterParams + [facilityId:(_stockFac ?: '__ALL_WAREHOUSES__')]).collect { key, value ->
        java.net.URLEncoder.encode(key, 'UTF-8') + '=' + java.net.URLEncoder.encode(value, 'UTF-8')
    }.join('&')

            import org.moqui.entity.EntityCondition
            def ef = ec.entity
            def _orgId = _stockOrgId

            // ZE-INV-001 f/u: Stock Value now matches the Inventory Dashboard. The by-facility view's
            // totalValue = sum(acquireCost) is 0 for MRP-priced stock (cost never set) AND it's sum-of-
            // costs, not sum(qty*cost). So value each unit from the Asset directly, valuationRate ->
            // acquireCost -> product MRP (same fallback as the dashboard / Expiry Risk). stockValueByRow
            // keys product|facility|lot to line up 1:1 with the view's rows (identical group-by), so the
            // per-row "Stock Value" column and the summary total are both correct + consistent.
            stockValueByRow = [:]
            def _mrpCache = [:]
            sumValue = 0.0G
            def _aq = ef.find("mantle.product.asset.Asset")
                        .condition("assetTypeEnumId", "AstTpInventory")
                        .condition("quantityOnHandTotal", EntityCondition.GREATER_THAN, 0G)
                        .condition("ownerPartyId", _orgId)
            if (_stockFac) _aq.condition("facilityId", _stockFac)
            for (a in _aq.list()) {
                def product = ef.find("mantle.product.Product").condition("productId", a.productId).useCache(true).one()
                if (product?.ownerPartyId != _orgId) continue
                def qoh = (a.quantityOnHandTotal ?: 0G) as java.math.BigDecimal
                def vr = a.valuationRate ? (a.valuationRate as java.math.BigDecimal) : null
                def ac = a.acquireCost ? (a.acquireCost as java.math.BigDecimal) : null
                def rate = (vr != null && vr > 0G) ? vr : ((ac != null && ac > 0G) ? ac : null)
                if (rate == null) {
                    def mrp = _mrpCache[a.productId]
                    if (mrp == null) {
                        mrp = (product.mrpAmount ?: 0G) as java.math.BigDecimal
                        _mrpCache[a.productId] = mrp
                    }
                    rate = mrp
                }
                def val = qoh * (rate ?: 0G)
                sumValue += val
                def k = (a.productId ?: '') + '|' + (a.facilityId ?: '') + '|' + (a.lotId ?: '')
                stockValueByRow[k] = (stockValueByRow[k] ?: 0G) + val
            }

            // Count each product once across warehouses/lots; empty lots do not make an
            // otherwise stocked product out of stock. Summary stays independent of list search/paging.
            sumQoh = 0.0G
            outCount = 0
            recentCount = 0
            def _productUnits = [:]
            def _recentSkus = new HashSet()
            def _nowMs = ec.user.nowTimestamp.getTime()
            def _weekMs = 604800000L
            for (def r in allStock) {
                def q = (r.totalQoh ?: 0)
                sumQoh = sumQoh + q
                if (r.productId) _productUnits[r.productId] = (_productUnits[r.productId] ?: 0G) + q
                if (r.lastUpdated != null) {
                    def age = _nowMs - r.lastUpdated.getTime()
                    if (age >= 0 && age < _weekMs && r.productId) _recentSkus.add(r.productId)
                }
            }
            skuCount = _productUnits.values().count { it > 0G }
            outCount = _productUnits.values().count { it <= 0G }
            recentCount = _recentSkus.size()
            stockLineCount = allStock.size()
